target.css:
:root {
  --ink: #20241f;
  --paper: #fffdf7;
  --cream: #f4eedf;
  --line: #d9d0bd;
  --coffee: #75452d;
  --orange: #e56b35;
  --gold: #d9a72c;
  --green: #4f7658;
  --muted: #777266;
}

.roast-card {
  box-sizing: border-box;
  width: 500px;
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--ink);
  border-radius: 14px;
  overflow: hidden;
}

.card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 13px 16px 11px;
  border-bottom: 1px solid var(--line);
}

.eyebrow {
  margin: 0 0 4px;
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1.1px;
}

.roast-card h1 {
  margin: 0;
  font-size: 20px;
  line-height: 1.1;
  letter-spacing: -0.35px;
}

.status {
  padding: 5px 8px;
  color: var(--green);
  background: var(--cream);
  border: 1px solid var(--green);
  border-radius: 999px;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.7px;
}

.console-grid {
  display: grid;
  grid-template-columns: 1.12fr 0.88fr;
  min-height: 151px;
}

.profile-panel {
  padding: 11px 13px 9px;
  border-right: 1px solid var(--line);
}

.panel-heading,
.chart-footer,
.card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.panel-heading {
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.7px;
}

.panel-heading strong {
  color: var(--orange);
  font-size: 15px;
  letter-spacing: 0;
}

.chart {
  position: relative;
  height: 85px;
  margin: 5px 0 3px 29px;
  border-bottom: 1px solid var(--line);
  background: repeating-linear-gradient(to bottom, transparent 0, transparent 27px, var(--cream) 28px);
}

.axis {
  position: absolute;
  left: -28px;
  color: var(--muted);
  font-size: 9px;
}

.axis-top { top: -4px; }
.axis-mid { top: 25px; }
.axis-low { top: 53px; }

.curve-line {
  position: absolute;
  right: 14px;
  bottom: 14px;
  width: 139px;
  height: 47px;
  border-top: 3px solid var(--orange);
  border-right: 3px solid var(--orange);
  border-radius: 0 60px 0 0;
  transform: skewY(-18deg);
}

.curve-dot {
  position: absolute;
  width: 7px;
  height: 7px;
  background: var(--paper);
  border: 2px solid var(--orange);
  border-radius: 50%;
}

.dot-one { bottom: 12px; left: 20px; }
.dot-two { bottom: 29px; left: 83px; }
.dot-three { top: 11px; right: 12px; }

.chart-footer {
  color: var(--muted);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.45px;
}

.metrics-panel {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: 10px 12px;
  background: var(--cream);
}

.metrics {
  display: grid;
  gap: 5px;
  padding: 0;
  margin: 0;
  list-style: none;
}

.metrics li {
  display: grid;
  grid-template-columns: 1fr auto;
  align-items: baseline;
  column-gap: 6px;
}

.metrics span {
  color: var(--muted);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.65px;
}

.metrics strong {
  font-size: 17px;
  line-height: 1;
}

.metrics em {
  grid-column: 2;
  color: var(--green);
  font-size: 9px;
  font-style: normal;
  font-weight: 800;
  text-align: right;
}

.metrics li:first-child em {
  color: var(--orange);
}

.metrics-panel button {
  padding: 7px 8px;
  color: var(--paper);
  background: var(--coffee);
  border: 1px solid var(--coffee);
  border-radius: 5px;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.2px;
}

.card-footer {
  padding: 9px 16px;
  color: var(--muted);
  border-top: 1px solid var(--line);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.45px;
}

.card-footer strong { color: var(--ink); }

.batch-code {
  color: var(--coffee);
  font-weight: 800;
}

.target {
  padding: 3px 6px;
  color: var(--coffee);
  background: var(--paper);
  border: 1px solid var(--gold);
  border-radius: 4px;
}

